$r|Select-Object reason,exit_code,wall_ms,summary,host_checks|ConvertTo-Json -Depth 6
if($r.reason -ne 'completed' -or -not $r.host_checks_pass -or $r.exit_code -ne 0){throw 'Product or host guard failed'}
$observed=@($r.summary.output_token_ids);$expected=@($oracle.expected.output_token_ids)
$same=$observed.Count -eq $expected.Count
for($i=0;$same -and $i -lt $expected.Count;$i++){if($observed[$i] -ne $expected[$i]){$same=$false}}
if(-not $same -or $r.summary.prompt_token_ids_fnv1a64 -ne $oracle.prompt.u32le_fnv1a64 -or -not $r.summary.first_token_raw_logit_available -or [Math]::Abs($r.summary.first_token_raw_logit-$oracle.expected.first_token_raw_logit) -gt $oracle.expected.first_token_raw_logit_tolerance){throw 'GB10 token/logit boundary failed'}
if(-not $r.summary.stream_matches_output -or -not $r.summary.callbacks_before_return -or $r.summary.stream_callback_count -ne $expected.Count){throw 'Actual stream callback boundary failed'}
$stderr=[IO.File]::ReadAllText((Join-Path $out 'product.stderr.log'))
$markers=@([regex]::Matches($stderr,'BATCH_MARK coarse_out_projection [^\r\n]*'))
if($CoarseOut -eq 1 -and $markers.Count -ne (10-$FinalQueryOutputLiveness)){throw 'Coarse owner did not cover all10 full-attention OUT projections'}
if($CoarseOut -eq 0 -and $markers.Count){throw 'Disabled coarse owner executed'}
foreach($marker in $markers){
 if($marker.Value -notmatch ' tokens=8192 rows=2048 k=4096 chunk=64 fragments=1 ' -or $marker.Value -notmatch ' hardware_error_bound_proven=0 completed=1$'){throw 'Coarse owner shape or completion mismatch'}
 $counts=[regex]::Match($marker.Value,' candidates=(\d+) dispatches=(\d+) workspace_bytes=295739396 ')
 if(-not $counts.Success){throw 'Coarse owner count metadata missing'}
 $n=[int64]$counts.Groups[1].Value;$dispatches=[int64]$counts.Groups[2].Value
 if($n -gt 16777216 -or $dispatches -ne [Math]::Ceiling($n/262144.0)){throw 'Coarse owner capacity or bounded dispatch mismatch'}
}
$expertMarkers=@([regex]::Matches($stderr,'BATCH_MARK moe_expert_order [^\r\n]*'))
if($expertMarkers.Count -ne (40*$ExpertOrder)){throw 'Expert-order activation count mismatch'}
foreach($marker in $expertMarkers){if($marker.Value -ne 'BATCH_MARK moe_expert_order tokens=8192 buckets=256 permutation_only=1 scratch_bytes=16780292 host_count_reads=0 original_candidates=1 original_k16=1 original_stream=1'){throw 'Expert-order identity mismatch'}}
if($stderr -match 'BATCH_MARK moe_shared_staged_half '){throw 'Shared staged replay unexpectedly active'}

$registerMarkers=@([regex]::Matches($stderr,'SM121_REGISTER_PV_RESCALE [^\r\n]*'))
if($registerMarkers.Count -ne ((10-$FinalQueryLiveness)*$RegisterPvRescale)){throw 'Register PV activation count mismatch'}
foreach($marker in $registerMarkers){if($marker.Value -ne 'SM121_REGISTER_PV_RESCALE query_start=0 query_count=8192 native_and_exact=1 original_k16=1 additional_workspace_bytes=0'){throw 'Register PV activation scope mismatch'}}
$exactMarkers=@([regex]::Matches($stderr,'SM121_EXACT_ATTENTION_PIPELINE [^\r\n]*'))
if($exactMarkers.Count -ne ((10-$FinalQueryLiveness)*$ExactAttentionPipeline)){throw 'Combined attention activation count mismatch'}
foreach($marker in $exactMarkers){if($marker.Value -ne ('SM121_EXACT_ATTENTION_PIPELINE query_start=0 query_count=8192 query_rows=32 key_columns='+$(if($NarrowDomain){'64'}else{'32'})+' exact_native_exp=1 verified_inputs=328728576 workspace_bytes=82182144')){throw 'Combined attention activation scope mismatch'}}
$expStorage=@([regex]::Matches($stderr,'SM121_NATIVE_EXP2_STORAGE [^\r\n]*'))
if($expStorage.Count -ne $ExactAttentionPipeline){throw 'Native EXP allocation count mismatch'}
foreach($marker in $expStorage){if($marker.Value -ne 'SM121_NATIVE_EXP2_STORAGE bytes=82182144 verified_inputs=328728576 source_table_unchanged=1'){throw 'Native EXP table verification missing'}}
if($stderr -match 'BATCH_MARK moe_down_consumer_filter '){throw 'Disabled MoE down filter executed'}
if($stderr -match 'BATCH_MARK moe_down_consumer_audit |BATCH_MARK moe_consumer_interval_audit |BATCH_MARK coarse_linear_out_projection |BATCH_MARK out_consumer_audit |BATCH_MARK out_variance_budget_audit |FLA_FUSED_STATE_OUTPUT |FLA_COARSE_INTERVAL |SM121_SELECTIVE_QK_EXACT_TAIL '){throw 'Disabled numerical experiment executed'}

$replayMarkers=@([regex]::Matches($stderr,'BATCH_MARK variance_linear_out_projection [^\r\n]*'))
if($replayMarkers.Count -ne (30*[int]($VarianceReplay -ne 0))){throw 'Adaptive linear OUT activation count mismatch'}
foreach($marker in $replayMarkers){
 if($marker.Value -notmatch ' tokens=8192 rows=2048 k=4096 radius=512 ppb=1000 ' -or $marker.Value -notmatch ' variant=2 workspace_bytes=170205188 completed_ms=[0-9.]+ original_k16=1 full_residual_norm_certificate=1 bounded_rounds=18 rounded_f32_carrier=1 completed=1$'){throw 'Adaptive linear OUT scope mismatch'}
}

$compactMarkers=@([regex]::Matches($stderr,'BATCH_MARK moe_down_consumer_compact [^\r\n]*'))
if($compactMarkers.Count -ne (40*$DownConsumerCompact)){throw 'Compact consumer activation count mismatch'}
foreach($marker in $compactMarkers){
 if($marker.Value -notmatch '^BATCH_MARK moe_down_consumer_compact tokens=8192 cells=16777216 ' -or $marker.Value -notmatch ' invalid_values=0 workspace_bytes=1056 full_unrounded_residual_certificate=1 original_selected_replay=1 shared_event_dependency=1 fused_collection=1 omission_bitmap_bytes=0 counter_identities_pass=1 redzones_pass=1 completed=1$'){throw 'Compact consumer scope mismatch'}
 $fields=@{};foreach($match in [regex]::Matches($marker.Value,'(\w+)=(\d+)')){$fields[$match.Groups[1].Value]=[int64]$match.Groups[2].Value}
 if($fields.selected -ne ($fields.skipped+$fields.replayed) -or $fields.selected -gt 134217728 -or $fields.invariant_cells -gt 16777216){throw 'Compact consumer count mismatch'}
}

$fusedMarkers=@([regex]::Matches($stderr,'SM121_FUSED_PROBABILITY_PV [^\r\n]*'))
if($fusedMarkers.Count -ne ((10-$FinalQueryLiveness)*$FusedProbabilityPv)){throw 'Fused probability PV activation count'}
foreach($m in $fusedMarkers){if($m.Value -ne 'SM121_FUSED_PROBABILITY_PV query_start=0 query_count=8192 independent_exact_qk=1 original_probability_recurrence=1 original_final_bound=1 original_exact_replay=1 additional_workspace_bytes=0 profile_stage1_includes_native_pv=1'){throw 'Fused consumer contract'}}

foreach($operation in @('scores','state','output')){
 $markers=@([regex]::Matches($stderr,('FLA_PAIRED_SCORE_ARENAS operation='+$operation+' [^\r\n]*')))
 if($markers.Count -ne (240*$PairedScoreArenas)){throw ('Paired GDN activation count: '+$operation)}
 foreach($m in $markers){
  $expected=if($operation -eq 'scores'){'FLA_PAIRED_SCORE_ARENAS operation=scores tokens=1024 shared_qk_heads=16 original_k16=1 additional_device_bytes=0'}elseif($operation -eq 'state'){'FLA_PAIRED_SCORE_ARENAS operation=state tokens=1024 columns=8 original_k16=1 additional_device_bytes=0 capture=0'}else{'FLA_PAIRED_SCORE_ARENAS operation=output tokens=1024 columns=8 original_k16=1 additional_device_bytes=0'}
  if($m.Value -ne $expected){throw ('Paired GDN activation contract: '+$operation)}
 }
}


$liveness=@([regex]::Matches($stderr,'BATCH_MARK final_query_liveness [^\r\n]*'))
if($liveness.Count -ne $FinalQueryLiveness){throw 'Terminal liveness activation count'}
foreach($m in $liveness){if($m.Value -ne 'BATCH_MARK final_query_liveness layer=39 tokens=8192 query_start=8191 query_count=1 full_prefix_qkv=1 original_kv_capture=1 unused_contexts_zeroed=1 downstream_full_shape=1 suffix_workspace_bytes=83886080 gb10_boundary_required=1'){throw 'Terminal liveness scope mismatch'}}
if($stderr -match 'BATCH_MARK layer39_q1_kv8192_activate '){throw 'Old terminal-prefill arithmetic route unexpectedly active'}

$outputLiveness=@([regex]::Matches($stderr,'BATCH_MARK final_query_output_liveness [^\r\n]*'))
if($outputLiveness.Count -ne $FinalQueryOutputLiveness){throw 'Terminal output activation count'}
foreach($m in $outputLiveness){if($m.Value -ne 'BATCH_MARK final_query_output_liveness layer=39 tokens=8192 live_rows=1 first_live_row=8191 output_features=2048 k=4096 original_k16=1 original_bf16_endpoint=1 dead_rows_zeroed=1 residual_norm_unchanged=1 additional_device_bytes=0 submitted=1'){throw 'Terminal output scope mismatch'}}

$narrowMarkers=@([regex]::Matches($stderr,'SM121_NARROW_DOMAIN_QK [^\r\n]*'))
if($narrowMarkers.Count -ne (9*$NarrowDomain)){throw 'Narrow-domain activation count'}
foreach($m in $narrowMarkers){
 if($m.Value -notmatch '^SM121_NARROW_DOMAIN_QK query_start=0 query_count=8192 query_rows=32 key_columns=64 window=64 bf16_exponents=95:159 classified_rows=147456 narrow_tiles=([0-9]+) original_tiles=([0-9]+) original_k16=1 complete_fallback=1 refreshed=1 workspace_bytes=589832 stream_drained=1$'){throw 'Narrow-domain activation scope'}
 if([int]$Matches[1] -le 0 -or [int]$Matches[2] -le 0 -or ([int]$Matches[1]+[int]$Matches[2]) -ne 266240){throw 'Narrow-domain tile coverage'}
}
if($stderr -match 'SM121_QK_RZ_TREE |BATCH_MARK moe_class_expert_order |BATCH_MARK moe_producer_gate '){throw 'Unqualified alternative active'}
if($stderr -match 'SM121_LONG_ATTENTION_PIPELINE '){throw 'Long route active outside its scope'}
exit 0
